from dataclasses import dataclass, field

VERSION = "dua 2.32.2"
GREEN = "\x1b[32m"
CYAN = "\x1b[36m"
RESET = "\x1b[39m"
VALID_FORMATS = ["metric", "binary", "bytes", "gb", "gib", "mb", "mib"]
DEFAULT_IGNORES = ["/proc", "/dev", "/sys", "/run"]

ROOT_HELP_LONG = """A tool to learn about disk usage, fast!

Usage: dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...

